package io.knowledgebrain.knowledge;
import java.time.Clock;
import java.util.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import jakarta.servlet.http.Cookie;
import org.springframework.web.server.ResponseStatusException;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;
class PublicKnowledgeApiTest {
    @Test void exactPublicActionAndFreshCookieAreForwardedAndPrivateVisibilityRejected(){var store=mock(ContributionStore.class);var concepts=mock(ConceptStore.class);var space=mock(SpaceAuthorizationClient.class);var browser=mock(ConceptController.class);var api=new PublicKnowledgeController(store,concepts,space,browser,new SimpleMeterRegistry(),"https://localhost:8443");var ids=new UuidV7(Clock.systemUTC());UUID id=ids.next(),concept=ids.next();var request=request("GET","");when(browser.parent(request)).thenReturn("00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01");when(concepts.get(id,concept)).thenReturn(new ConceptStore.Concept(concept,id,"PRIVATE","ACTIVE",1,"Secret","",java.time.Instant.now(),java.time.Instant.now()));assertThatThrownBy(()->api.concept(id,concept,request)).isInstanceOf(ResponseStatusException.class);verify(space).authorize(eq(id),eq("x".repeat(43)),eq("PUBLIC_CONCEPT_READ"),eq("PUBLIC"),anyString());}
    @Test void originDuplicateCookieDuplicateJsonAndMissingReviewVersionNeverMutate()throws Exception{var store=mock(ContributionStore.class);var concepts=mock(ConceptStore.class);var space=mock(SpaceAuthorizationClient.class);var browser=mock(ConceptController.class);var api=new PublicKnowledgeController(store,concepts,space,browser,new SimpleMeterRegistry(),"https://localhost:8443");when(browser.parent(any())).thenReturn("00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01");var ids=new UuidV7(Clock.systemUTC());UUID id=ids.next(),proposal=ids.next();var cross=request("POST","{}");cross.removeHeader("Origin");cross.addHeader("Origin","https://evil.invalid");assertThatThrownBy(()->api.submit(id,cross)).isInstanceOf(ResponseStatusException.class);var duplicate=request("POST","{}");duplicate.setCookies(new Cookie("__Host-brain_guest","x".repeat(43)),new Cookie("__Host-brain_guest","y".repeat(43)));assertThatThrownBy(()->api.submit(id,duplicate)).isInstanceOf(ResponseStatusException.class);var json=request("POST","{\"conceptId\":null,\"baseVersion\":0,\"title\":\"a\",\"title\":\"b\",\"description\":\"\",\"rationale\":\"r\"}");assertThatThrownBy(()->api.submit(id,json)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->api.review(id,proposal,request("POST","{\"decision\":\"APPROVED\",\"reason\":\"r\"}"))).isInstanceOf(ResponseStatusException.class).satisfies(e->assertThat(((ResponseStatusException)e).getStatusCode().value()).isEqualTo(428));verifyNoInteractions(store);}
    private MockHttpServletRequest request(String method,String body){var r=new MockHttpServletRequest(method,"/api/public/spaces/x/contributions");r.setSecure(true);r.setContentType("application/json");r.addHeader("Origin","https://localhost:8443");r.setCookies(new Cookie("__Host-brain_guest","x".repeat(43)));r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
}
